def _attach_property_decision_summary(property_obj: TripProperty) -> Any:
    preferences = list(
        property_obj.preferences.select_related("family_group", "updated_by").all()
    )
    counts = {"LOVE": 0, "MAYBE": 0, "PASS": 0}
    for preference in preferences:
        counts[preference.stance] += 1

    property_summary = cast(Any, property_obj)
    property_summary.preference_list = preferences
    property_summary.preference_counts = counts
    property_summary.preference_response_count = len(preferences)
    return property_summary


def _get_editable_family_ids(request: HttpRequest, trip: Trip) -> set[str]:
    user = cast(User, request.user)
    family_ids = active_families(trip).values_list("id", flat=True)
    return {
        str(family_id)
        for family_id in FamilyMembership.objects.filter(
            user=user,
            family_id__in=family_ids,
            is_active=True,
        ).values_list("family_id", flat=True)
    }


@login_required
@feature_required("trips")
def property_list(request: HttpRequest, trip_pk: str) -> HttpResponse:
    """
    Display a list of properties for a trip.

    Args:
        request: The HTTP request
        trip_pk: The primary key of the trip

    Returns:
        HttpResponse: The rendered template
    """
    trip = get_object_or_404(Trip, pk=trip_pk, deleted_at__isnull=True)
    _check_trip_permission(request, trip)  # Check permission

    properties = [
        _attach_property_decision_summary(property_obj)
        for property_obj in trip.properties.prefetch_related(
            "preferences__family_group",
            "preferences__updated_by",
        )
    ]
    has_any_preferences = any(
        property_obj.preference_response_count for property_obj in properties
    )

    context = {
