    trip.properties.update(is_primary=False)

    # Set this property as primary
    property_obj.is_primary = True
    property_obj.save()

    messages.success(request, f"'{property_obj.name}' set as primary property.")
    return redirect("trips:property_detail", trip_pk=trip.pk, pk=property_obj.pk)
