    @action(detail=True, methods=["get"])
    def sync_status(self, request: Request, pk: str | None = None) -> Response:
        """Get real-time sync status for this calendar account"""
        calendar = self.get_object()
        user = cast("User", request.user)

        # Check if user is the owner
        if calendar.user != request.user and not user.is_staff:
            return Response(
                {
                    "detail": "You do not have permission to view sync status for this calendar."
                },
                status=status.HTTP_403_FORBIDDEN,
            )

        try:
            # Get the latest sync log
            latest_sync = calendar.sync_logs.order_by("-started_at").first()

            # Calculate sync status
            is_syncing = False
            sync_status = "idle"
            progress_percentage = 0
            last_error = None

            if latest_sync:
                if latest_sync.status in {"QUEUED", "RUNNING"}:
                    is_syncing = True
                    sync_status = "syncing"
                    # Calculate progress based on some logic
                    progress_percentage = 50  # Placeholder
                elif latest_sync.status == "FAILED":
                    sync_status = "error"
                    last_error = latest_sync.error_message
                elif latest_sync.status == "SUCCESS":
                    sync_status = "completed"
                    progress_percentage = 100
                elif latest_sync.status == "REAUTH_REQUIRED":
                    sync_status = "error"
                    last_error = (
                        latest_sync.error_message or "Reauthorization required."
                    )

            conflicts_count = (
                calendar.modified_events.count() + calendar.deleted_events.count()
            )

            status_data = {
                "is_syncing": is_syncing,
                "last_sync": calendar.last_synced,
                "sync_status": sync_status,
                "progress_percentage": progress_percentage,
                "conflicts_count": conflicts_count,
                "last_error": last_error,
            }

            serializer = SyncStatusSerializer(status_data)
            return Response(serializer.data)

        except Exception as e:
            logger.error(
                f"Failed to get sync status for calendar {calendar.id}: {str(e)}"
            )
            return Response(
                {"detail": "Failed to retrieve sync status."},
                status=status.HTTP_500_INTERNAL_SERVER_ERROR,
            )

