        selected_calendars = serializer.validated_data["selected_calendars"]
        sync_enabled = serializer.validated_data.get("sync_enabled", True)

        try:
            with transaction.atomic():
                # Update the calendar's selected calendars
                # For Google Calendar, this might involve storing the calendar IDs
                # For ICS, this might not be applicable

                if calendar.provider == "GOOGLE":
                    # Store the selected calendar IDs in a JSON field or related model
                    # For now, we'll just update the calendar_id field with the primary selection
                    if selected_calendars:
                        calendar.calendar_id = selected_calendars[
                            0
                        ]  # Use first as primary

                calendar.sync_enabled = sync_enabled
                calendar.save()

                # Log the calendar selection
                logger.info(
                    f"Calendar selection updated for {calendar.id}: {selected_calendars}"
                )

                # Trigger a sync if enabled
                if sync_enabled:
                    try:
                        from calendars.tasks import sync_calendar as sync_calendar_task

                        transaction.on_commit(
                            lambda cid=calendar.id: sync_calendar_task.delay(cid)  # type: ignore[misc]
                        )
                        logger.info(
                            f"Sync task scheduled after calendar selection for {calendar.id}"
                        )
                    except Exception as e:
                        logger.error(
                            f"Failed to schedule sync after calendar selection for {calendar.id}: {str(e)}"
                        )

                return Response(
